  "confidence": 0.9,
  "reasoning": "The request asks to copy a reusable set of about twenty tasks for new client onboardings, which is a template capability. None of the candidates offers creating new projects or tasks from a saved template, and Subtasks is a nested-task structure rather than a reusable copy.",
  "rejected_candidates": [
    {
      "feature_id": 5,
      "reason": "Bulk edit changes fields on existing tasks in one action; it does not create a copy of a task set."
    },
    {
      "feature_id": 1,
      "reason": "Task dependencies define blocking relationships between tasks, not duplicating a setup."
    },
    {
      "feature_id": 8,
      "reason": "Real-time co-editing concerns simultaneous editing of task descriptions, unrelated to copying a setup."
    },
    {
      "feature_id": 10,
      "reason": "A daily digest email summarizes changes and has no connection to creating reusable task sets."
    },
    {
      "feature_id": 2,
      "reason": "Subtasks nest smaller tasks within a task; it does not provide a reusable, copyable set of tasks across projects."
    }
  ]
}
